import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Validate a discount percent value.
 * @param {any} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  if (discountPercent === undefined || discountPercent === null) {
    return true;
  }
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }}
 * @returns {import('./result.js').Result}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate date format YYYY-MM-DD
  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate it's a real date
  const date = new Date(issueDate + 'T00:00:00Z');
  if (isNaN(date.getTime()) || date.toISOString().split('T')[0] !== issueDate) {
    return fail('DATE_INVALID');
  }

  // Validate lines array is not empty
  if (!lines || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  // Process lines
  const processedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discount
    if (!isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate SKU exists
    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return productResult;
    }

    const product = productResult.value;
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    processedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: processedLines,
  });
}

/**
 * Calculate the total for a line item (before discount).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return Math.max(0, line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const discount = lineTotal(line) * ((line.discountPercent ?? 0) / 100);
  return Math.max(0, discount);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = Math.max(0, invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));
  const discount = Math.max(0, invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0));
  const total = Math.max(0, subtotal - discount);
  return {
    subtotal,
    discount,
    total,
  };
}

/**
 * Add or update a line on an invoice.
 * @param {any} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {import('./result.js').Result}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Validate invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  // Validate discount
  if (!isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }

  // Validate SKU exists
  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return productResult;
  }

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex !== -1) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discountPercent ?? 0,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {any} invoice
 * @param {string} sku
 * @returns {import('./result.js').Result}
 */
export function removeLine(invoice, sku) {
  // Validate invoice is draft
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  // Check if SKU exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) {
    return fail('LINE_NOT_FOUND');
  }

  // Check if it's the last line
  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing its status to 'issued'.
 * @param {any} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already used
 * @returns {import('./result.js').Result}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

