test('invoiceTotals correctly calculates with tier discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
    ],
  });

  const invoice = result.value;
  const totals = invoiceTotals(invoice);

  // DES-HOUR is 8500 per hour (vatRate 21%), qty 2 = 17000 subtotal
  // 5% discount (gold tier) = 850
  // After discount: 16150
  // VAT (21% of 16150) = 3392 (rounded)
  assert.strictEqual(totals.subtotal, 17000);
  assert.strictEqual(totals.discount, 850);
  assert.strictEqual(totals.vat, 3392);
  assert.strictEqual(totals.total, 19542);
});

