  const line = { qty: 5, unitPrice: 1000, vatRate: 9 };
  // 5000 * 0.09 = 450
  assert.strictEqual(lineVat(line), 450);
});

test('lineVat with 21% VAT', () => {
  const line = { qty: 5, unitPrice: 1000, vatRate: 21 };
  // 5000 * 0.21 = 1050
  assert.strictEqual(lineVat(line), 1050);
});

test('lineVat calculated on amount after discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // Subtotal: 5000
  // Discount: 500
  // After discount: 4500
  // VAT: 4500 * 0.21 = 945
  assert.strictEqual(lineVat(line), 945);
});

test('lineVat with 100% discount and VAT results in 0', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 100, vatRate: 21 };
  // After discount: 0
  // VAT: 0 * 0.21 = 0
  assert.strictEqual(lineVat(line), 0);
});

test('lineVat rounds to nearest cent', () => {
  const line = { qty: 3, unitPrice: 333, vatRate: 21 };
  // Subtotal: 999
  // VAT: 999 * 0.21 = 209.79 → rounds to 210
  assert.strictEqual(lineVat(line), 210);
});

test('invoiceTotals with single VAT rate', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 2000, VAT: 420
  assert.deepStrictEqual(totals, {
    subtotal: 2000,
    discount: 0,
    vat: 420,
    total: 2420,
  });
});

test('invoiceTotals with multiple VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 1000, vatRate: 0 },
      { qty: 1, unitPrice: 1000, vatRate: 9 },
      { qty: 1, unitPrice: 1000, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 3000
  // VAT: 0 + 90 + 210 = 300
  assert.deepStrictEqual(totals, {
    subtotal: 3000,
    discount: 0,
    vat: 300,
    total: 3300,
  });
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 2000
  // Discount: 200
  // After discount: 1800
  // VAT: 1800 * 0.21 = 378
  // Total: 2000 - 200 + 378 = 2178
  assert.deepStrictEqual(totals, {
    subtotal: 2000,
    discount: 200,
    vat: 378,
    total: 2178,
  });
});

test('invoiceTotals with multiple lines, discounts, and VAT', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000, discountPercent: 10, vatRate: 21 },
      { qty: 3, unitPrice: 2000, discountPercent: 0, vatRate: 9 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Line 1: 2000 - 200 + (1800 * 0.21 = 378) = 2178
  // Line 2: 6000 - 0 + (6000 * 0.09 = 540) = 6540
  // Subtotal: 8000, Discount: 200, VAT: 378 + 540 = 918
  // Total: 8000 - 200 + 918 = 8718
  assert.deepStrictEqual(totals, {
    subtotal: 8000,
    discount: 200,
    vat: 918,
    total: 8718,
  });
});

test('invoiceTotals with all discounts and VAT', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 100, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 5000
  // Discount: 5000
  // After discount: 0
  // VAT: 0
  // Total: 5000 - 5000 + 0 = 0
  assert.deepStrictEqual(totals, {
    subtotal: 5000,
    discount: 5000,
    vat: 0,
    total: 0,
  });
});

